  "action-node": {
    "install": "npm install framer-motion lucide-react clsx tailwind-merge",
    "usage": "import { ActionNode } from \"./ActionNode\";\nimport \"./ActionNode.css\";\n\n<ActionNode\n  bounce={30}\n  corner={28}\n  fill=\"dark\"\n  stroke={true}\n/>",
    "codeTsx": "import { type ReactNode, useEffect, useState } from \"react\";\nimport { AnimatePresence, motion } from \"framer-motion\";\nimport { Sparkles, Check, X, ArrowDown, Heart, Bookmark } from \"lucide-react\";\n\n/* == Action node ===================================================\n   An automation step card with its controls folded into the corner.\n   ============================================================== */\n\ninterface ActionNodeProps {\n  bounce?: number;\n  corner?: number;\n  fill?: \"light\" | \"dark\";\n  stroke?: boolean;\n  className?: string;\n}\n\nexport function ActionNode({\n  bounce = 30,\n  corner = 28,\n  fill = \"dark\",\n  stroke = true,\n  className = \"\",\n}: ActionNodeProps) {\n  const [active, setActive] = useState(false);\n  const [count, setCount] = useState(0);\n\n  const spring = {\n    type: \"spring\",\n    stiffness: 300 + bounce * 3,\n    damping: 25,\n  };\n\n  return (\n    <div\n      className={\"relative select-none flex items-center justify-center p-4 \" + className}\n      style={{ borderRadius: corner + \"px\" }}\n    >\n      <motion.div\n        whileHover={{ scale: 1.03 }}\n        whileTap={{ scale: 0.97 }}\n        animate={{ scale: active ? 1.05 : 1 }}\n        transition={{ spring }}\n        onClick={() => {\n          setActive(!active);\n          setCount((c) => c + 1);\n        }}\n        className={\"px-6 py-4 rounded-full font-semibold transition-colors flex items-center gap-3 cursor-pointer shadow-lg \" + (\n          fill === \"light\"\n            ? \"bg-white text-neutral-900 border border-black/5\"\n            : \"bg-[#16171b] text-white border border-white/10\"\n        )}\n      >\n        <span className=\"text-sm tracking-tight\">Action node</span>\n        <motion.span\n          animate={{ rotate: active ? 180 : 0 }}\n          transition={{ spring }}\n          className=\"text-xs opacity-70\"\n        >\n          ●\n        </motion.span>\n      </motion.div>\n    </div>\n  );\n}",
    "codeCss": ".action-node-root {\n  --bn-corner: 28px;\n  --bn-bounce: 30;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: var(--bn-corner);\n  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.action-node-active {\n  box-shadow: 0 12px 32px -4px rgba(0, 0, 0, 0.25);\n}",
    "howItWorks": "/* The handle follows the finger exactly and the offset is\n   taken at the FIRST MOVE, never at the press. Deciding it on\n   pointerdown is what makes a slider teleport: a press away\n   from the handle sets the offset to the handle's own middle\n   and the first move jumps it the whole way in one frame. */\nconst move = (e) => {\n  const at = local(e.clientX);\n  if (grab === null) { grab = at - x.get(); return; }\n  x.set(clamp(at - grab, 0, TRAVEL));\n};\n\n/* And the commit is a MORPH, not a hand-over. The handle's\n   width and its offset move together and by the same amount,\n   so the right edge is stationary and the handle opens out\n   behind itself to fill the track it crossed. A scale would\n   have dragged the corner radius with it. */\nanimate(x, TRAVEL, spring);\nsetDone(true);          /* width: GRIP -> span - PAD * 2 */"
  },
