    "codeCss": ".search-root {\n  --bn-corner: 28px;\n  --bn-bounce: 30;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: var(--bn-corner);\n  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n}\n\n.search-active {\n  box-shadow: 0 12px 32px -4px rgba(0, 0, 0, 0.25);\n}",
